text(await tools.exec_command({cmd:`cat > /tmp/alh-template.html <<'EOF'
<!doctype html>
<html lang="es">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#f8f6ef">
<title>La Alhambra · Ruta en 3D</title>
<style>
@font-face{font-family:DM Sans;src:url(data:font/woff2;base64,@@DM@@) format("woff2");font-weight:400 700;font-display:swap}
@font-face{font-family:Playfair;src:url(data:font/woff2;base64,@@PLAY@@) format("woff2");font-weight:600 700;font-display:swap}
:root{color-scheme:light;--paper:#f8f6ef;--card:#fffdf8;--ink:#272b23;--muted:#5c6256;--line:#e5e0d5;--rust:#a54129;--rust-dark:#85321f;--tint:#f9eee6;--green:#3d5744}
*{box-sizing:border-box}
body{margin:0;background:var(--paper);color:var(--ink);font:400 15px/1.5 "DM Sans",system-ui,sans-serif}
button,a{-webkit-tap-highlight-color:transparent}
button{font:inherit;color:inherit;cursor:pointer}
button:focus-visible,a:focus-visible,.stage:focus-visible{outline:2px solid var(--rust);outline-offset:4px}
button[disabled]{opacity:.4;cursor:default}
a{color:inherit}
.wrap{max-width:1520px;width:calc(100% - 112px);margin-inline:auto}
.top{border-bottom:1px solid var(--line)}
.top .wrap{height:72px;display:flex;align-items:center;justify-content:space-between;gap:12px}
.brand,.location{display:flex;align-items:center;gap:11px}
.brand{font-size:15px;font-weight:700;letter-spacing:-.025em}
.logo{display:grid;place-items:center;width:37px;height:37px;border-radius:10px;background:var(--rust);color:#fff7eb}
.location{gap:7px;font-size:13px;font-weight:600;color:var(--muted)}
.location .icon{color:var(--rust)}
.icon{width:18px;height:18px;display:block;flex:none;fill:none;stroke:currentColor;stroke-width:1.65;stroke-linecap:round;stroke-linejoin:round}
