  }
});
byId("prev").addEventListener("click", () => select(active - 1, true));
byId("next").addEventListener("click", () => {
  if (active < sites.length - 1) {
    select(active + 1, true);
  } else {
    setGuided(false);
    model.reset();
    byId("progress").textContent = "Ruta completada";
    byId("next").querySelector("span").textContent = "Repetir";
    active = sites.length;
  }
});
byId("next").addEventListener("click", restartIfComplete, {capture:true});
function restartIfComplete(event) {
  if (active === sites.length) {
    event.stopImmediatePropagation();
    setGuided(true);
    select(0, true);
  }
}
byId("prev").addEventListener("click", event => {
  if (active === sites.length) {
    event.stopImmediatePropagation();
    select(sites.length - 2, true);
  }
}, {capture:true});
byId("overview").addEventListener("click", () => {model.reset(); byId("reset").focus();});
byId("reset").addEventListener("click", () => model.reset());
byId("zoom-in").addEventListener("click", () => model.zoom(1.23));
byId("zoom-out").addEventListener("click", () => model.zoom(1/1.23));

const hill = [[-117,-12],[-111,-26],[-92,-36],[-66,-40],[-37,-41],[-11,-37],[18,-33],[44,-31],[62,-21],[71,-4],[67,16],[53,33],[27,44],[-1,47],[-28,45],[-53,44],[-80,38],[-104,30],[-120,13]];
const gardenHill = [[67,-33],[73,-48],[82,-63],[99,-74],[116,-75],[130,-64],[138,-49],[133,-36],[121,-26],[104,-20],[89,-19],[76,-23]];

function buildScene() {
  const T = window.THREE;
  const renderer = new T.WebGLRenderer({antialias:true, alpha:true});
  renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 1.75));
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = T.PCFSoftShadowMap;
  renderer.shadowMap.autoUpdate = false;
  const scene = new T.Scene();
  const camera = new T.OrthographicCamera(-140,140,80,-80,1,700);
  byId("scene").append(renderer.domElement);

  scene.add(new T.HemisphereLight(0xfff7e4,0xb8ae96,1.85));
  const sun = new T.DirectionalLight(0xffecd0,2.15);
  sun.position.set(-93,135,-63);
  sun.castShadow = true;
  Object.assign(sun.shadow.camera,{left:-160,right:160,top:147,bottom:-147,near:10,far:390});
  sun.shadow.mapSize.set(2048,2048);
  sun.shadow.normalBias = .32;
  sun.shadow.bias = -.0003;
  scene.add(sun);
  const shadow = new T.Mesh(new T.PlaneGeometry(1000,1000),new T.ShadowMaterial({opacity:.19}));
  shadow.rotation.x = -Math.PI/2;
  shadow.position.y = -21.1;
  shadow.receiveShadow = true;
  scene.add(shadow);

  let seed = 512;
  function random() {
    seed = (Math.imul(seed,1664525) + 1013904223) >>> 0;
    return seed / 4294967296;
  }
  const pick = colors => colors[Math.floor(random()*colors.length)];
  const materials = new Map();
  const batch = new Map();
  function paint(color) {
    if (!materials.has(color)) materials.set(color,new T.MeshStandardMaterial({color,roughness:.92,flatShading:true,side:T.DoubleSide}));
    return materials.get(color);
  }
  const boxGeo = new T.BoxGeometry(1,1,1);
  const leafGeo = new T.IcosahedronGeometry(1,0);
  const cypressGeo = new T.CylinderGeometry(.24,1.08,1,6,3);
  const trunkGeo = new T.CylinderGeometry(.6,1,1,5);
  const diskGeo = new T.CylinderGeometry(1,1,1,32);
  const composer = new T.Object3D();
  function stamp(geometry,color,x,y,z,w,h,d,angle = 0,casts = true) {
    const key = geometry.id + "|" + color + "|" + casts;
    if (!batch.has(key)) batch.set(key,{geometry,color,casts,matrices:[]});
    composer.position.set(x,y,z);
    composer.rotation.set(0,angle,0);
    composer.scale.set(w,h,d);
    composer.updateMatrix();
    batch.get(key).matrices.push(composer.matrix.clone());
  }
  const block = (x,y,z,w,h,d,color,angle = 0,casts = true) =>
    stamp(boxGeo,color,x,y,z,w,h,d,angle,casts);
  function mesh(vertices,color,casts = true) {
    const geometry = new T.BufferGeometry();
    geometry.setAttribute("position",new T.Float32BufferAttribute(vertices.flat(),3));
    geometry.computeVertexNormals();
    const item = new T.Mesh(geometry,paint(color));
    item.castShadow = casts;
    item.receiveShadow = true;
    scene.add(item);
  }
  function surface(points,y,color) {
    const v = points.map(([x,z]) => new T.Vector2(x,z));
    mesh(T.ShapeUtils.triangulateShape(v,[]).flatMap(indices => indices.map(i => [v[i].x,y,v[i].y])),color,false);
  }
  function terrain(poly,cx,cz,top) {
    surface(poly,top,"#a5a67a");
    const edge = poly.map(([x,z]) => [x,top,z]);
    const rings = [[1.07,top-4],[1.22,-11],[1.32,-20.5]].map(([scale,y]) => poly.map(([x,z]) => [
      cx+(x-cx)*(scale+random()*.077), y+random()*2.5, cz+(z-cz)*(scale+random()*.13)
    ]));
    rings.forEach((ring, layer) => {
      const upper = layer === 0 ? edge : rings[layer-1];
      const shades = [
        ["#989663","#a4a270","#aaa573","#99996b"],
        ["#b1a077","#b4a682","#ac9c75","#9d936e","#bba784"],
        ["#a79c7a","#b8ac8b","#aea07d","#9e9375"]
      ][layer];
      const faces = new Map();
      for(let i=0;i<ring.length;i++){
        const j = (i+1)%ring.length;
        for (const face of [[upper[i],ring[i],upper[j]],[ring[i],ring[j],upper[j]]]) {
          const color = pick(shades);
          if(!faces.has(color)) faces.set(color,[]);
          faces.get(color).push(...face);
        }
      }
      for (const [color,vertices] of faces) mesh(vertices,color);
    });
  }
  terrain(hill,-29,1,0);
  terrain(gardenHill,104,-47,3);
  const stone="#bf936f", plaster="#d8b18b", lightStone="#e1bf98", cap="#e2bf97", roof="#a8523c", roofShade="#a05644", brick="#a47958", earth="#c4b18a";

  function strip(points,width,y,color,casts=false) {
    let distance = 0;
    for(let i=1;i<points.length;i++){
      const [a,b] = [points[i-1],points[i]];
      const dx=b[0]-a[0], dz=b[1]-a[1], length=Math.hypot(dx,dz);
      if (length < .001) continue;
      block((a[0]+b[0])/2,typeof y==="function" ? y((a[0]+b[0])/2) : y,(a[1]+b[1])/2,length+.36,.21,width,color,-Math.atan2(dz,dx),casts);
      distance += length;
    }
    return distance;
  }
  function wall(x1,z1,x2,z2,h=7,battlements=true,base=0) {
    const dx=x2-x1,dz=z2-z1,len=Math.hypot(dx,dz),angle=-Math.atan2(dz,dx),x=(x1+x2)/2,z=(z1+z2)/2;
    block(x,base+h/2,z,len,h,2.2,stone,angle);
    block(x,base+h-.35,z,len+.2,.7,2.55,cap,angle);
    if (battlements) for(let t=.04;t<=.96;t+=3.05/len) block(x1+dx*t,base+h+.6,z1+dz*t,1.47,1.24,2.18,plaster,angle);
  }
  function tower(x,z,w,h,d,base=0) {
    block(x,base+h/2,z,w,h,d,stone);
    block(x,base+.5,z,w+.75,1,d+.75,brick);
    block(x,base+h-.5,z,w+.48,1,d+.48,cap);
    block(x,base+h+.07,z,w-.85,.15,d-.85,"#a48664");
    for (const sign of [-1,1]) {
      for (let k=-w/2+.7;k<=w/2-.55;k+=2.35) block(x+k,base+h+.7,z+sign*(d/2-.55),1.2,1.4,1.15,plaster);
      for (let k=-d/2+2.25;k<=d/2-1.15;k+=2.35) block(x+sign*(w/2-.55),base+h+.7,z+k,1.15,1.4,1.2,plaster);
      block(x,base+h*.66,z+sign*(d/2+.04),.75,2.05,.13,"#75563e");
      block(x+sign*(w/2+.04),base+h*.66,z,.13,2.05,.75,"#75563e");
    }
  }
  function building(x,z,w,d,h,base=0,{wallColor=plaster,tile=roof,rise=2.4,windows=true}={}) {
    block(x,base+h/2,z,w,h,d,wallColor);
    block(x,base+h-.25,z,w+.46,.52,d+.45,lightStone);
    const left=x-w/2-.38,right=x+w/2+.38,front=z+d/2+.41,back=z-d/2-.41,y=base+h,hip=Math.min(w*.16,d*.25);
    const a=[left,y,back], b=[right,y,back], c=[right,y,front], f=[left,y,front];
    const p=[left+hip,y+rise,z],q=[right-hip,y+rise,z];
    mesh([a,b,q,a,q,p],tile);
    mesh([f,p,q,f,q,c],tile);
    mesh([a,p,f,b,c,q],roofShade);
    if (windows) {
      for(let xx=x-w/2+1.5;xx<x+w/2-1;xx+=2.8) {
        block(xx,base+h*.58,z+d/2+.025,.59,h*.29,.095,"#775e47");
        block(xx,base+h*.58,z-d/2-.025,.59,h*.29,.095,"#775e47");
      }
      for(let zz=z-d/2+1.55;zz<z+d/2-1;zz+=2.8) block(x+w/2+.024,base+h*.58,zz,.1,h*.27,.59,"#836349");
    }
  }
  function court(x,z,w,d,y=0){
    block(x,y+.14,z,w,.28,d,"#c8b08a",0,false);
    block(x,y+.30,z,w-1.1,.10,d-1.1,"#dfc59c",0,false);
  }
  function pool(x,z,w,d,y=0){
    block(x,y+.36,z,w+.8,.26,d+.8,"#e1c8a3",0,false);
    block(x,y+.51,z,w,.07,d,"#6f9d94",0,false);
    block(x-w*.28,y+.55,z,w*.1,.025,d*.78,"#85afa0",0,false);
  }
  function hedge(x,z,w,d,y=0){
    block(x,y+.61,z,w,1.22,d,"#6d8050");
    block(x,y+1.21,z,w-.15,.16,d-.13,"#82935b");
  }
  const green=["#5e7753","#648055","#788951","#667c4e","#81915c","#53714c"];
  function tree(x,z,y=0,size=1,tall=false) {
    const leaf=pick(green);
    stamp(trunkGeo,"#806548",x,y+.9*size,z,.31*size,1.8*size,.31*size);
    if (tall) {
      const h=(4.8+random()*3.4)*size;
      stamp(cypressGeo,leaf,x,y+.85*size+h*.48,z,1.0*size,h,1.0*size,random());
      stamp(cypressGeo,leaf,x,y+.95*size+h*.75,z,.74*size,h*.58,.74*size,random());
    } else {
      const r=(1.28+random()*.9)*size;
      stamp(leafGeo,leaf,x,y+2.1*size,z,r,r*.96,r,random()*6.28);
      stamp(leafGeo,pick(green),x+r*.34,y+2.45*size,z-r*.24,r*.72,r*.75,r*.72,random()*6.28);
    }
  }

  // Alcazaba and the curtain wall along the Sabika ridge.
  surface([[-112,-12],[-104,-21],[-77,-17],[-68,5],[-72,22],[-106,19]],.11,earth);
  for (const [a,b] of [
    [[-110,-11],[-101,-22]],[[-101,-22],[-78,-19]],[[-78,-19],[-70,-8]],
    [[-70,-8],[-72,8]],[[-75,18],[-91,20]],[[-91,20],[-104,15]],[[-104,15],[-110,-11]]
  ]) wall(...a,...b,7.2);
  tower(-108,-7,9,17,10);
  tower(-101,16,6.8,9,6.5);
  tower(-79,-18,8.2,13.5,8.2);
  tower(-72,15,6.6,10,7);
  block(-108,18.2,-7,.28,3,.28,"#91654a");
  block(-106.65,19.35,-7,2.6,1.12,.12,"#b6533c");
  for(let i=0;i<4;i++) for(let j=0;j<2;j++){
    const x=-100+i*6.2,z=-9+j*7.2;
    block(x,1,z,4.5,2,4.5,"#b99a71");
    block(x,2.02,z,3.2,.1,3.15,"#d9ba93");
  }
  wall(-90,28,-55,34,3.6,true);
  wall(-55,34,-23,38,4.2,true);
  wall(-23,38,10,39,4.2,true);
  wall(10,39,40,32,3.8,true);
  tower(-56,34,5.4,7.1,5.3);
  tower(10,39,5.2,7.8,5.2);
  wall(-66,-25,-54,-29,4.8);
  wall(0,-28,18,-24,4.9);
  wall(34,-25,54,-20,4.25);
  tower(54,-20,5.2,7,5.5);

  // Square exterior and circular courtyard of the Palacio de Carlos V.
  const px=-45,pz=10,span=22.5;
  court(px,pz,25,25);
  for (const sign of [-1,1]){
    block(px+sign*span/2,4.35,pz,3.25,8.7,span+3.2,"#bf9a77");
    block(px,4.35,pz+sign*span/2,span-3.2,8.7,3.25,"#bf9a77");
    for(const y of [1.15,4.25,8.65]){
      block(px+sign*span/2,y,pz,3.7,.37,span+3.6,cap);
      block(px,y,pz+sign*span/2,span-3,.37,3.7,cap);
    }
    for (let j=-9;j<=9;j+=3){
      for(const y of [2.8,6.2]){
        block(px+sign*13.0,y,pz+j,.12,1.3,.64,"#8d6b53");
        block(px+j,y,pz+sign*13.0,.64,1.3,.12,"#8d6b53");
      }
    }
  }
  for(let i=0;i<32;i++){
    const angle=i*Math.PI/16;
    const x=px+Math.cos(angle)*8.0,z=pz+Math.sin(angle)*8.0;
    block(x,8.2,z,1.8,.6,1.7,"#ad785c",-angle);
    stamp(trunkGeo,"#d1ae8c",x,4.0,z,.28,7.7,.28);
    block(x,4.25,z,1.82,.32,1.25,"#d1ae8c",-angle);
  }
  stamp(diskGeo,"#ddc19e",px,.47,pz,7.8,.13,7.8,0,false);

  // Palacios Nazaríes: Comares, the Patio de los Arrayanes and neighbouring courts.
  court(-35,-16,41,20);
  building(-49,-15,8,14,6);
  building(-44,-25,10,8,6.4);
  tower(-34,-28,12,15.8,10);
  court(-34,-17,15,16);
  pool(-34,-17,3.6,11);
  hedge(-38.5,-17,1.25,11);
  hedge(-29.5,-17,1.25,11);
  building(-34,-8.8,13,4.6,5.3);
  building(-22,-21,7.8,12,7);
  building(-15,-26,8.2,8.6,6.1);
  court(-13,-18,12.5,8.5);
  building(-6.9,-17,5.6,12,6.2);
  building(-13.5,-11,9,3.5,5.0);
  stamp(diskGeo,"#dfc9a9",-13.4,.64,-17.5,1.1,.6,1.1);
  for(let x=-18;x<-7;x+=1.7) for(const z of [-14.3,-21.2]) stamp(trunkGeo,lightStone,x,1.35,z,.19,2.5,.19);

  // The Partal pool, portico and terraced garden.
  court(22,-18,23,17);
  pool(22,-17,9.8,7.2);
  building(22,-24.7,15,4.6,5.3);
  tower(29,-27,5.8,10.1,5.2);
  for(let x=15.5;x<=27;x+=2.0) stamp(trunkGeo,lightStone,x,1.55,-22,.31,2.95,.31);
  for(const z of [0,9,18]){
    court(28,z,28,5.1);
    hedge(17,z,5,2.85); hedge(36,z,9.5,2.85);
    for(const x of [12,21,32,42]) tree(x,z,0,.76,true);
  }
  building(52,19,13,11,5.2);
  building(41,23,8.5,9,4.6);
  building(52,8,9.2,5.7,4.5);
  building(-16,28,10.5,7.5,5.8);
  building(-3,24,12,8,5.3);
  tower(-55,26,5.7,11.7,5.7);
  building(-57,23,4.7,8.4,4.7);

  // The Generalife gardens and the long central canal.
  court(105,-47,40,32,3);
  court(104,-51,22,24,3);
  pool(104,-51,2.6,17,3);
  for (const x of [98.7,109.3]) for(const z of [-55,-46]){
    hedge(x,z,5,5.9,3);
    tree(x,z,3,.46);
  }
  building(104,-64,20,6.4,7,3);
  building(103.5,-37.5,19,5.7,5.9,3);
  building(115.2,-53,5,17,5.8,3);
  building(119.2,-64,6.6,7.1,10,3);
  for(let x=95;x<=112;x+=2.1) stamp(trunkGeo,lightStone,x,4.7,-60.3,.29,3.3,.29);
  for(let x=89;x<=122;x+=5.5) tree(x,-28.3,3,.85,true);
  for(let z=-64;z<=-35;z+=5.3) {tree(86,z,3,.8,true);tree(125,z,3,.73,true);}
  for (const z of [-29,-25]) wall(90,z,119,z,1.2,false,3);

  for(let i=0;i<215;i++){
    const x=-116+random()*181,z=-38+random()*85;
    const margin=(x>-101&&x<52&&z>26+4*Math.sin(x*.045)&&z<39+5*Math.cos(x*.045))
      || (x>48&&x<62&&z>-16&&z<3)
      || (x>-9&&x<41&&z>24&&z<35)
      || (x>-83&&x<-57&&z<-22&&z>-31)
      || (x>-65&&x<-56&&z>-15&&z<12);
    if(margin) tree(x,z,0,.66+random()*.5,random()<.55);
  }
  for(let i=0;i<107;i++){
    const x=-113+random()*174,z=41+random()*14;
    const edge=47-0.0015*(x+13)*(x+13);
    if(z>edge&&z<edge+10) tree(x,z,-4-(z-edge)*.53,.65+random()*.43,random()<.3);
  }

  const walkY = x => x < 59 ? .75 : x < 89 ? .75+(x-59)*.105 : 3.9;
  const routeMesh = [];
  let cursor = 0;
  for(let i=1;i<walk.length;i++){
    const [x1,z1]=walk[i-1], [x2,z2]=walk[i];
    const dx=x2-x1,dz=z2-z1,distance=Math.hypot(dx,dz);
    const n=Math.ceil(distance/1.7);
    for(let j=0;j<n;j++){
      const t=j/n,next=(j+1)/n;
      const a=new T.Vector3(x1+dx*t,walkY(x1+dx*t),z1+dz*t);
      const b=new T.Vector3(x1+dx*next,walkY(x1+dx*next),z1+dz*next);
      if(cursor++%3!==2) routeMesh.push([a,b]);
    }
  }
  // Low bridge between the two hills.
  const bridgeA = new T.Vector3(60,.4,-10.8), bridgeB = new T.Vector3(86,3.2,-27.4);
  const bridgeMid = bridgeA.clone().lerp(bridgeB,.5), bridgeDelta = bridgeB.clone().sub(bridgeA);
  const bridge = new T.Mesh(new T.BoxGeometry(bridgeDelta.length(),.8,4.4), paint("#bea885"));
  bridge.position.copy(bridgeMid);
  bridge.quaternion.setFromUnitVectors(new T.Vector3(1,0,0),bridgeDelta.normalize());
  bridge.castShadow = bridge.receiveShadow = true;
  scene.add(bridge);
  for(const x of [68,75,82]) block(x,-3,-10.8-(x-60)*.64,1.8,9.6,3.6,"#a99775");
  strip(walk.filter(([x])=>x<61),4.15,.18,"#c8ba91");
  strip(walk.filter(([x])=>x>=90),3.5,3.20,"#d6bf94");
  const routeMaterial = new T.MeshBasicMaterial({color:"#a8452a"});
  const haloMaterial = new T.MeshBasicMaterial({color:"#fff2d2"});
  for (const [a,b] of routeMesh) {
    // Visibility above the walls keeps the schematic itinerary legible as the model turns.
    for (const [material,width,dy,order] of [[haloMaterial,1.14,0,1],[routeMaterial,.67,.028,2]]) {
      const ribbon = new T.Mesh(new T.BoxGeometry(a.distanceTo(b)+.11,.04,width),material);
      ribbon.position.copy(a).lerp(b,.5);
      ribbon.position.y += dy;
      ribbon.quaternion.setFromUnitVectors(new T.Vector3(1,0,0),b.clone().sub(a).normalize());
      ribbon.renderOrder = order;
      scene.add(ribbon);
    }
  }
  for(const site of sites) {
    const ring = new T.Mesh(new T.RingGeometry(1.1,1.5,24),new T.MeshBasicMaterial({color:"#a8452a",side:T.DoubleSide}));
    ring.position.set(site.x,walkY(site.x)+.06,site.z);
    ring.rotation.x = -Math.PI/2;
    scene.add(ring);
  }
  for (const batchItem of batch.values()) {
    const {geometry,color,casts,matrices} = batchItem;
    const item = new T.InstancedMesh(geometry,paint(color),matrices.length);
    matrices.forEach((matrix,i) => item.setMatrixAt(i,matrix));
    item.castShadow = casts;
    item.receiveShadow = true;
    scene.add(item);
  }
  renderer.shadowMap.needsUpdate = true;

  const initial = {yaw:.31, polar:.94, zoom:1, x:4, z:-9, y:0};
  const view = {...initial}, target = {...initial};
  const motion = matchMedia("(prefers-reduced-motion: reduce)");
  let width = 1, height = 1, frame = 0;
  function tick() {
    frame = 0;
    let moving = false;
    for(const key of Object.keys(view)){
      const difference = target[key]-view[key];
      if(Math.abs(difference)<.002 || motion.matches){
        view[key] = target[key];
      }else{
        view[key] += difference*.17;
        moving = true;
      }
    }
    const range = 350, y = Math.cos(view.polar)*range, radius = Math.sin(view.polar)*range;
    camera.position.set(view.x+Math.sin(view.yaw)*radius,view.y+y,view.z+Math.cos(view.yaw)*radius);
    camera.lookAt(view.x,view.y,view.z);
    const aspect = width/height;
    const halfWidth = Math.max(151,aspect*83) / view.zoom;
    const halfHeight = halfWidth/aspect;
    Object.assign(camera,{left:-halfWidth,right:halfWidth,top:halfHeight,bottom:-halfHeight});
    camera.updateProjectionMatrix();
    renderer.render(scene,camera);
    const projected = new T.Vector3();
    sites.forEach(({pin},i) => {
      projected.set(...pin).project(camera);
      const x=(projected.x+1)*width/2,z=(1-projected.y)*height/2;
      pins[i].hidden = x < 20 || x > width-20 || z < 54 || z > height-12;
      pins[i].style.left = x + "px";
      pins[i].style.top = z + "px";
    });
    const north = new T.Vector3().set(view.x,view.y,view.z-30).project(camera);
    byId("north").style.transform = "rotate(" + Math.atan2(north.x*width,north.y*height) + "rad)";
    if(moving) schedule();
  }
  function schedule(){ if(!frame) frame=requestAnimationFrame(tick); }
  new ResizeObserver(() => {
    width = stage.clientWidth;
    height = stage.clientHeight;
    if (width && height) {
      renderer.setSize(width,height,false);
      schedule();
    }
  }).observe(stage);

  const clamp = T.MathUtils.clamp;
  const zoom = factor => {
    target.zoom = clamp(target.zoom*factor,.7,4);
    byId("overview").hidden = false;
    schedule();
  };
  function rotate(dx,dy){
    target.yaw -= dx*.009;
    target.polar = clamp(target.polar-dy*.008,.40,1.30);
    byId("overview").hidden = false;
    schedule();
  }
  const pointers = new Map();
  const point = event => [event.clientX,event.clientY];
  function separation(){
    const [a,b]=pointers.values();
    return Math.hypot(a[0]-b[0],a[1]-b[1]);
  }
  stage.addEventListener("pointerdown",event => {
    if(event.target.closest("button") || event.button!==0 || pointers.size>=2) return;
    stage.setPointerCapture(event.pointerId);
    pointers.set(event.pointerId,point(event));
  });
  stage.addEventListener("pointermove",event => {
    if(!pointers.has(event.pointerId)) return;
    const previous = pointers.get(event.pointerId);
    const distance = pointers.size===2 ? separation() : 0;
    const current = point(event);
    pointers.set(event.pointerId,current);
    if(distance>0) zoom(separation()/distance);
    else rotate(current[0]-previous[0],current[1]-previous[1]);
  });
  for(const name of ["pointerup","pointercancel","lostpointercapture"]) {
    stage.addEventListener(name,event => pointers.delete(event.pointerId));
  }
  stage.addEventListener("wheel",event => {
    event.preventDefault();
    zoom(Math.exp(clamp(-event.deltaY*(event.deltaMode===1?.044:.0017),-.34,.34)));
  },{passive:false});
  stage.addEventListener("keydown",event => {
    if(event.target!==stage) return;
    const actions = {ArrowLeft:()=>rotate(-25,0),ArrowRight:()=>rotate(25,0),ArrowUp:()=>rotate(0,19),ArrowDown:()=>rotate(0,-19),"+":()=>zoom(1.23),"=":()=>zoom(1.23),"-":()=>zoom(1/1.23),Home:reset,Escape:reset};
    if(Object.hasOwn(actions,event.key)){
