      actions[event.key]();
    }
  });
  function reset(){
    Object.assign(target,initial,{yaw:initial.yaw+Math.round((view.yaw-initial.yaw)/(2*Math.PI))*2*Math.PI});
    byId("overview").hidden = true;
    schedule();
  }
