      schedule();
    }
  };
}

function buildFallback() {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  byId("scene").replaceChildren(canvas);
  byId("fallback-message").hidden = false;
  stage.querySelector(".map-tag span").textContent = "Plano del recinto";
  stage.querySelector(".instructions").hidden = true;
  let center = [5,-16], scale = 1, width = 1, height = 1;
  function draw(){
    width = stage.clientWidth;
    height = stage.clientHeight;
    const ratio = Math.min(devicePixelRatio || 1,2);
    canvas.width = width*ratio;
    canvas.height = height*ratio;
    ctx.setTransform(ratio,0,0,ratio,0,0);
    const size=Math.min(width/300,height/155)*scale;
    const project=([x,z])=>[width/2+(x-center[0])*size,height/2+(z-center[1])*size];
    function path(points,fill){
      ctx.beginPath();
      for(const p of points) ctx.lineTo(...project(p));
      if(fill){ctx.closePath();ctx.fillStyle=fill;ctx.fill();}
      else ctx.stroke();
    }
    path(hill,"#a9ae86");
    path(gardenHill,"#a9ae86");
    ctx.lineJoin="round";
    ctx.lineCap="round";
    ctx.strokeStyle="#fff4dc";
    ctx.lineWidth=6;
    path(walk);
    ctx.strokeStyle="#a8452a";
    ctx.setLineDash([4,4]);
    ctx.lineWidth=2.4;
    path(walk);
    ctx.setLineDash([]);
    sites.forEach(({x,z},i) => {
      const [left,top]=project([x,z]);
      pins[i].hidden=left<18 || left>width-18 || top<45 || top>height;
      Object.assign(pins[i].style,{left:left+"px",top:top+"px"});
    });
  }
  new ResizeObserver(draw).observe(stage);
  return {
    zoom(factor){scale=Math.max(.8,Math.min(2.8,scale*factor));byId("overview").hidden=false;draw();},
    reset(){center=[5,-16];scale=1;byId("overview").hidden=true;draw();},
    focus(point){center=point;scale=1.85;byId("overview").hidden=false;draw();}
  };
}
let model;
try {
  model = buildScene();
} catch (error) {
  console.info("Vista esquemática:",error.message);
  model = buildFallback();
}
setGuided(false);
select(0);
