function createCanvasRenderer(T) {
  const canvas = document.createElement("canvas");
  canvas.className = "software";
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("El navegador no admite Canvas.");
  const light = new T.Vector3(-.54,.79,-.36).normalize();
  const basis = new T.Matrix4();
  const instance = new T.Matrix4();
  const a = new T.Vector3(), b = new T.Vector3(), c = new T.Vector3();
  const normal = new T.Vector3(), edge = new T.Vector3();
  const view = new T.Matrix4();
  let ratio = 1, width = 1, height = 1, faces;

  function prepare(scene) {
    scene.updateMatrixWorld(true);
    const triangles = [];
    scene.traverse(object => {
      if (!object.isMesh || object.material.isShadowMaterial) return;
      const {attributes,index} = object.geometry;
      const position = attributes.position;
      const count = index ? index.count : position.count;
      const color = object.material.color.clone().convertLinearToSRGB();
      const ground = Boolean(object.userData.ground);
      const copies = object.isInstancedMesh ? object.count : 1;
      for (let copy=0;copy<copies;copy++) {
        basis.copy(object.matrixWorld);
        if (object.isInstancedMesh) {
          object.getMatrixAt(copy,instance);
          basis.multiply(instance);
        }
        for (let i=0;i<count;i+=3) {
          a.fromBufferAttribute(position,index ? index.getX(i) : i).applyMatrix4(basis);
          b.fromBufferAttribute(position,index ? index.getX(i+1) : i+1).applyMatrix4(basis);
          c.fromBufferAttribute(position,index ? index.getX(i+2) : i+2).applyMatrix4(basis);
          normal.subVectors(b,a).cross(edge.subVectors(c,a)).normalize();
          if (ground && Math.abs(normal.y)>.95) normal.y=1;
          const diffuse = ground ? Math.abs(normal.dot(light)) : Math.max(0,normal.dot(light));
          const brightness = object.material.isMeshBasicMaterial ? 1 : .81 + .26*diffuse;
          const fill = "rgb(" + [color.r,color.g,color.b].map(channel => Math.min(255,Math.round(channel*255*brightness))).join(",") + ")";
          triangles.push({points:[a.x,a.y,a.z,b.x,b.y,b.z,c.x,c.y,c.z],fill,ground,
            flat:Math.abs(normal.y)>.95, priority:object.renderOrder, screen:new Float32Array(6),depth:0});
        }
      }
    });
    return triangles;
  }
  return {
    domElement:canvas,
    setPixelRatio(value){ratio=value;},
    setSize(w,h){width=w;height=h;canvas.width=w*ratio;canvas.height=h*ratio;},
    render(scene,camera){
      if (!faces) faces=prepare(scene);
      camera.updateMatrixWorld(true);
      const matrix = view.multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse).elements;
      const visible=[];
      const halfWidth=width/2, halfHeight=height/2;
      for (const face of faces) {
        const {points,screen}=face;
        let depth=0;
        for (let i=0;i<3;i++){
          const x=points[i*3],y=points[i*3+1],z=points[i*3+2];
          screen[i*2]=(matrix[0]*x+matrix[4]*y+matrix[8]*z+matrix[12]+1)*halfWidth;
          screen[i*2+1]=(1-matrix[1]*x-matrix[5]*y-matrix[9]*z-matrix[13])*halfHeight;
          depth+=matrix[2]*x+matrix[6]*y+matrix[10]*z+matrix[14];
        }
        const [ax,ay,bx,by,cx,cy]=screen;
        const winding=(bx-ax)*(cy-ay)-(by-ay)*(cx-ax);
        if ((!face.ground && !face.flat && winding>=0) || Math.abs(winding)<.1 ||
            Math.min(ax,bx,cx)>width || Math.max(ax,bx,cx)<0 || Math.min(ay,by,cy)>height || Math.max(ay,by,cy)<0) continue;
        face.depth=depth;
        visible.push(face);
      }
      visible.sort((a,b)=>Number(b.ground)-Number(a.ground) || b.depth-a.depth || a.priority-b.priority);
      ctx.setTransform(ratio,0,0,ratio,0,0);
      ctx.clearRect(0,0,width,height);
      ctx.lineWidth=.65;
      ctx.lineJoin="round";
      for (const {screen,fill} of visible) {
        ctx.beginPath();
        ctx.moveTo(screen[0],screen[1]);
        ctx.lineTo(screen[2],screen[3]);
        ctx.lineTo(screen[4],screen[5]);
        ctx.closePath();
        ctx.fillStyle=ctx.strokeStyle=fill;
        ctx.fill();
        ctx.stroke();
      }
    }
  };
}

