assert.equal(scripts.length,2);
function run(width,height,canvasAvailable=true){
 const {document,Event}=parseHTML(file.replace(/<script>[\\s\\S]*?<\\/script>/g,''));
 const by=id=>document.getElementById(id), stage=by('stage'), frames=[];
 Object.defineProperties(stage,{clientWidth:{value:width},clientHeight:{value:height}});
 const original=document.createElement.bind(document);
 document.createElement=(tag,...rest)=>{
  const el=original(tag,...rest);
  if(tag==='canvas'){
   const native=createCanvas(1,1);
   Object.defineProperties(el,{width:{get:()=>native.width,set:v=>native.width=v},height:{get:()=>native.height,set:v=>native.height=v}});
   el.native=native;
   el.getContext=(type)=>type==='2d'&&canvasAvailable?native.getContext('2d'):null;
  }
  return el;
 };
 class ResizeObserver{constructor(callback){this.callback=callback}observe(){this.callback()}}
 const consoleStub={error(){},warn(){},info(...args){ if(canvasAvailable) throw Error(args.join(' ')); }};
 const context=vm.createContext({document,devicePixelRatio:1,ResizeObserver,requestAnimationFrame:callback=>frames.push(callback),matchMedia:()=>({matches:true}),console:consoleStub});
 context.window=context;
 for(const script of scripts) vm.runInContext(script,context);
 function flush(){while(frames.length)frames.shift()()}
 function click(el){el.dispatchEvent(new Event('click',{bubbles:true}));flush()}
 function key(target,value){
  const e=new Event('keydown',{bubbles:true,cancelable:true});
  Object.defineProperty(e,'key',{value});
  target.dispatchEvent(e);flush();
 }
 flush();
 return {by,stage,flush,click,key,doc:document};
}
const {by,stage,click,key,doc}=run(982,490);
assert.equal(by('fallback-message').hidden,true);
assert.equal(doc.querySelectorAll('.pin:not([hidden])').length,5);
const canvas=doc.querySelector('#scene canvas').native;
const pixels=canvas.getContext('2d').getImageData(0,0,982,490).data;
let count=0;
for(let a=3;a<pixels.length;a+=4)if(pixels[a]>200)count++;
assert(count>35000, 'Rendered geometry should cover a substantial part of the canvas');
fs.writeFileSync('/tmp/alh-map.png',canvas.toBuffer('image/png'));
const first=doc.querySelector('.pin');
const initial=first.style.left;
key(stage,'ArrowRight');assert.notEqual(first.style.left,initial);
click(by('reset'));assert.equal(first.style.left,initial);
click(by('start'));assert.equal(by('start').querySelector('span').textContent,'Salir de la ruta');
assert.equal(by('overview').hidden,false);
click(by('next'));assert.equal(by('progress').textContent,'Parada 2 de 5');
click(by('prev'));assert.equal(by('progress').textContent,'Parada 1 de 5');
for(let i=0;i<5;i++)click(by('next'));
assert.equal(by('progress').textContent,'Ruta completada');
click(by('next'));assert.equal(by('progress').textContent,'Parada 1 de 5');
click(by('overview'));click(doc.querySelector('.pin:last-child'));
assert.equal(by('progress').textContent,'Parada 5 de 5');
click(by('zoom-out')); click(by('zoom-in'));
const mobile=run(360,326);
assert.equal(mobile.doc.querySelectorAll('.pin:not([hidden])').length,5);
fs.writeFileSync('/tmp/alh-map-mobile.png',mobile.doc.querySelector('#scene canvas').native.toBuffer('image/png'));
console.log('HTML final: render 3D probado con Canvas a dos tamaños, cinco marcadores, teclado, pasos, reinicio y zoom.');
EOF
